def validate_items(items):
    if not items:
        raise ValueError("No items provided")
    for item in items:
        if item['price'] <= 0 or item['quantity'] <= 0:
            raise ValueError("Invalid price or quantity")

def calculate_subtotal(items, is_vip):
    subtotal = sum(item['price'] * item['quantity'] for item in items)
    if is_vip:
        subtotal *= 0.9
    tax_rate = 0.08
    tax = subtotal * tax_rate
    return subtotal + tax

def format_receipt(items, total):
    receipt = "Receipt:\n"
    for item in items:
        receipt += f"{item['name']}: ${item['price']} x {item['quantity']} = ${item['price'] * item['quantity']}\n"
    receipt += f"Total: ${total:.2f}"
    return receipt

def process_order(items, is_vip):
    validate_items(items)
    total = calculate_subtotal(items, is_vip)
    return format_receipt(items, total)
